PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS pools(id TEXT PRIMARY KEY, enabled INTEGER NOT NULL CHECK(enabled IN(0,1)), consent_version TEXT NOT NULL, grant_cap INTEGER NOT NULL CHECK(grant_cap BETWEEN 0 AND 1000000000000), issued INTEGER NOT NULL DEFAULT 0 CHECK(issued>=0 AND issued<=grant_cap));
CREATE TABLE IF NOT EXISTS members(id TEXT PRIMARY KEY, pool TEXT NOT NULL REFERENCES pools(id), role TEXT NOT NULL CHECK(role IN('requester','worker','verifier','operator')), token_hash TEXT UNIQUE NOT NULL, enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN(0,1)), consent TEXT);
CREATE TABLE IF NOT EXISTS devices(id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES members(id), pubkey TEXT UNIQUE NOT NULL, enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN(0,1)), proved INTEGER NOT NULL DEFAULT 0 CHECK(proved IN(0,1)), challenge TEXT, challenge_expires INTEGER, model TEXT NOT NULL, first_layer INTEGER NOT NULL CHECK(first_layer>=0), end_layer INTEGER NOT NULL CHECK(end_layer>first_layer), max_jobs INTEGER NOT NULL CHECK(max_jobs BETWEEN 1 AND 4));
CREATE TABLE IF NOT EXISTS models(pool TEXT NOT NULL REFERENCES pools(id), digest TEXT NOT NULL, layers INTEGER NOT NULL CHECK(layers BETWEEN 1 AND 256), max_context INTEGER NOT NULL CHECK(max_context BETWEEN 1 AND 32768), enabled INTEGER NOT NULL CHECK(enabled IN(0,1)), PRIMARY KEY(pool,digest));
CREATE TABLE IF NOT EXISTS tariffs(pool TEXT NOT NULL REFERENCES pools(id), version TEXT NOT NULL, base INTEGER NOT NULL CHECK(base>=0), prefill INTEGER NOT NULL CHECK(prefill>=0), decode INTEGER NOT NULL CHECK(decode>=0), PRIMARY KEY(pool,version));
CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY, pool TEXT NOT NULL REFERENCES pools(id), kind TEXT NOT NULL CHECK(kind IN('issuance','treasury','available','escrow')), owner TEXT NOT NULL, balance INTEGER NOT NULL DEFAULT 0 CHECK(balance BETWEEN -1000000000000 AND 1000000000000 AND (kind='issuance' OR balance>=0)), UNIQUE(pool,kind,owner));
CREATE TABLE IF NOT EXISTS journal(id TEXT PRIMARY KEY, pool TEXT NOT NULL REFERENCES pools(id), idem TEXT NOT NULL, kind TEXT NOT NULL, request_hash TEXT NOT NULL, created INTEGER NOT NULL, UNIQUE(pool,idem));
CREATE TABLE IF NOT EXISTS entries(tx TEXT NOT NULL REFERENCES journal(id), account TEXT NOT NULL REFERENCES accounts(id), amount INTEGER NOT NULL CHECK(amount!=0 AND amount BETWEEN -1000000000000 AND 1000000000000), PRIMARY KEY(tx,account));
CREATE TABLE IF NOT EXISTS quotes(id TEXT PRIMARY KEY, pool TEXT NOT NULL REFERENCES pools(id), requester TEXT NOT NULL REFERENCES members(id), model TEXT NOT NULL, tariff TEXT NOT NULL, input_units INTEGER NOT NULL CHECK(input_units>0), max_output INTEGER NOT NULL CHECK(max_output>0), maximum INTEGER NOT NULL CHECK(maximum>0), expires INTEGER NOT NULL, used INTEGER NOT NULL DEFAULT 0 CHECK(used IN(0,1)), FOREIGN KEY(pool,model) REFERENCES models(pool,digest), FOREIGN KEY(pool,tariff) REFERENCES tariffs(pool,version));
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY, pool TEXT NOT NULL REFERENCES pools(id), requester TEXT NOT NULL REFERENCES members(id), quote TEXT UNIQUE NOT NULL REFERENCES quotes(id), idem TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('running','settled','cancelled','expired','failed')), expires INTEGER NOT NULL, delivered INTEGER, charged INTEGER, resolution_tx TEXT REFERENCES journal(id), UNIQUE(requester,idem));
CREATE TABLE IF NOT EXISTS assignments(id TEXT PRIMARY KEY, job TEXT NOT NULL REFERENCES jobs(id), device TEXT NOT NULL REFERENCES devices(id), first_layer INTEGER NOT NULL, end_layer INTEGER NOT NULL CHECK(end_layer>first_layer), epoch INTEGER NOT NULL CHECK(epoch=1), UNIQUE(job,first_layer), UNIQUE(job,device));
CREATE TABLE IF NOT EXISTS receipts(assignment TEXT PRIMARY KEY REFERENCES assignments(id), body TEXT NOT NULL, signature TEXT NOT NULL, digest TEXT NOT NULL, output_units INTEGER NOT NULL, input_units INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN('pending','verified','rejected')), verifier TEXT REFERENCES members(id));
CREATE TABLE IF NOT EXISTS disputes(id TEXT PRIMARY KEY, job TEXT NOT NULL REFERENCES jobs(id), owner TEXT NOT NULL REFERENCES members(id), reason TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('open','approved','rejected','resolved')), reviewer TEXT REFERENCES members(id), compensation INTEGER NOT NULL DEFAULT 0 CHECK(compensation>=0), UNIQUE(job,owner));
CREATE TABLE IF NOT EXISTS grants(pool TEXT NOT NULL REFERENCES pools(id), member TEXT NOT NULL REFERENCES members(id), amount INTEGER NOT NULL CHECK(amount>0), PRIMARY KEY(pool,member));
CREATE TABLE IF NOT EXISTS events(seq INTEGER PRIMARY KEY AUTOINCREMENT, pool TEXT NOT NULL REFERENCES pools(id), actor TEXT NOT NULL, kind TEXT NOT NULL, subject TEXT NOT NULL, created INTEGER NOT NULL, detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY, pool TEXT NOT NULL REFERENCES pools(id), kind TEXT NOT NULL, subject TEXT NOT NULL, created INTEGER NOT NULL, delivered INTEGER NOT NULL DEFAULT 0 CHECK(delivered IN(0,1)));
CREATE TRIGGER IF NOT EXISTS journal_no_update BEFORE UPDATE ON journal BEGIN SELECT RAISE(ABORT,'immutable journal'); END;
CREATE TRIGGER IF NOT EXISTS journal_no_delete BEFORE DELETE ON journal BEGIN SELECT RAISE(ABORT,'immutable journal'); END;
CREATE TRIGGER IF NOT EXISTS entries_no_update BEFORE UPDATE ON entries BEGIN SELECT RAISE(ABORT,'immutable entries'); END;
CREATE TRIGGER IF NOT EXISTS entries_no_delete BEFORE DELETE ON entries BEGIN SELECT RAISE(ABORT,'immutable entries'); END;
CREATE TRIGGER IF NOT EXISTS tariff_no_update BEFORE UPDATE ON tariffs BEGIN SELECT RAISE(ABORT,'immutable tariff'); END;
CREATE TRIGGER IF NOT EXISTS tariff_no_delete BEFORE DELETE ON tariffs BEGIN SELECT RAISE(ABORT,'immutable tariff'); END;
CREATE TRIGGER IF NOT EXISTS events_no_update BEFORE UPDATE ON events BEGIN SELECT RAISE(ABORT,'immutable audit'); END;
CREATE TRIGGER IF NOT EXISTS events_no_delete BEFORE DELETE ON events BEGIN SELECT RAISE(ABORT,'immutable audit'); END;
